/* GENERATED by scripts/build-atlas-data.cjs from atlas/graph/ — do not hand-edit. */
/* questions details for region "waves", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("waves.questions",{"questions":{
"q-float-sink-0":{"target":{"node":"float-sink","href":"../physics/matter/float-sink/#step1"},"prompts":[{"node":"float-sink","ask":{"zh":"橡皮泥捏成船以后，它排开的水是变多了还是变少了？排开的水越重，浮力怎样变？","en":"Once the plasticine is shaped into a boat, does it displace more water or less? And the heavier the displaced water, the stronger or weaker the buoyant force?"}},{"node":"net-force","ask":{"zh":"船浮在水面不动时，浮力和重力哪个大？两者相等意味着什么？","en":"When the boat floats still on the water, is the buoyant force bigger than gravity or equal to it? What does that equality mean?"}}],"reveal":{"zh":"捏成船排开的水变多了，浮力等于排开水的重量，变大到足以托住橡皮泥；浮起来静止时浮力与重力相等。","en":"Shaped into a boat it displaces more water, and buoyant force equals the weight of that water — now large enough to hold the plasticine up; floating still means buoyant force equals gravity."},"source":"../physics/matter/float-sink/#step1","lesson":"float-sink"},
"q-sound-vibration-0":{"target":{"node":"sound-vibration","href":"../physics/waves/sound-vibration/#step2"},"prompts":[{"node":"sound-vibration","ask":{"zh":"敲鼓时鼓面在动，放在鼓面上的米粒为什么会跳起来？","en":"When you beat a drum, why do rice grains sitting on the drumhead jump?"}},{"node":"oscillation","ask":{"zh":"鼓面振动得越快、幅度越大，听到的声音在音高和响度上各有什么变化？","en":"If the drumhead vibrates faster and with a bigger swing, what changes in pitch and in loudness?"}}],"reveal":{"zh":"声音就是物体的振动传到耳朵：振动越快音越高，幅度越大声越响，没有介质传不过去。","en":"Sound is an object's vibration reaching your ears: faster vibration means higher pitch, bigger swing means louder sound, and with no medium it cannot travel at all."},"source":"../physics/waves/sound-vibration/#step2","lesson":"sound-vibration"},
"q-buoyancy-archimedes-0":{"target":{"node":"buoyancy-archimedes","href":"../physics/matter/buoyancy-archimedes/#step1"},"prompts":[{"node":"buoyancy-archimedes","ask":{"zh":"钢的密度比水大得多，空心船排开的水和实心钢块排开的水，哪个更重？","en":"Steel is far denser than water — which displaces heavier water, a hollow ship or a solid steel block?"}},{"node":"net-force","ask":{"zh":"船浮着不动时，浮力和重力什么关系？浮力 F = ρ液·g·V排 里，哪个量是船的设计能改变的？","en":"While the ship floats still, how do buoyant force and gravity compare? In F = ρ·g·V, which quantity can the ship's design change?"}}],"reveal":{"zh":"船是空心的，排开的水很重，浮力等于排开水的重量，大到足以托住钢船；浮着时浮力与重力相等。","en":"A ship is hollow, so it displaces very heavy water; buoyant force equals the weight of that water, enough to hold up the steel, and while floating it equals gravity."},"source":"../physics/matter/buoyancy-archimedes/#step1","lesson":"buoyancy-archimedes"},
"q-eye-vision-0":{"target":{"node":"eye-vision","href":"../physics/optics/eye-vision/#step2"},"prompts":[{"node":"eye-vision","ask":{"zh":"近视是眼轴偏长，焦点落在视网膜前还是后？要把焦点往后推，该用会聚光的透镜还是发散光的透镜？","en":"In short-sightedness the eyeball is too long, so does the focus fall in front of or behind the retina? To push it back, do you need a converging or a diverging lens?"}},{"node":"snell","ask":{"zh":"光从空气进入透镜会折射——凹透镜让光发散还是会聚？发散之后焦点往哪个方向移？","en":"Light refracts entering a lens — does a concave lens spread light out or bring it together? And which way does spreading move the focus?"}}],"reveal":{"zh":"近视焦点在视网膜前，凹透镜把光发散开，焦点后移到视网膜上；远视正好相反。","en":"In short-sightedness the focus lands in front of the retina; a concave lens spreads the light so the focus shifts back onto the retina. Long-sightedness is the reverse."},"source":"../physics/optics/eye-vision/#step2","lesson":"eye-vision"},
"q-lens-0":{"target":{"node":"convex-lens","href":"../physics/optics/lens/#step2"},"prompts":[{"node":"convex-lens","ask":{"zh":"把字放在一倍焦距以内，像是实像还是虚像、正立还是倒立？","en":"With the text inside one focal length, is the image real or virtual, upright or inverted?"}},{"node":"snell","ask":{"zh":"光穿过凸透镜为什么会往中间偏？","en":"Why does light bend toward the middle as it passes through a convex lens?"}}],"reveal":{"zh":"字在一倍焦距以内时，折射后的光不再相交，眼睛顺着它们的反向延长线看到一个正立、放大的虚像。屏接不住这个像，只能透过透镜去看。","en":"With the text inside one focal length, the refracted rays no longer meet; the eye traces them back and sees an upright, magnified virtual image. No screen can catch it — you can only look through the lens."},"source":"../physics/optics/lens/#step2","lesson":"lens"},
"q-pressure-0":{"target":{"node":"pressure","href":"../physics/matter/pressure/#step0"},"prompts":[{"node":"pressure","ask":{"zh":"同样的力，接触面积越小压强越大——针尖和手指按同一个图钉，哪个压强大？","en":"The same force on a smaller area means higher pressure — pressing one drawing pin, is the pressure bigger at the point or at the flat end?"}},{"node":"work-energy","ask":{"zh":"密闭液体中压强处处相等——小活塞上加小力，大活塞为什么能顶起大重物？能量从哪里来？","en":"Pressure is equal everywhere in a sealed liquid — why can a small force on a small piston lift a big weight on a big piston? Where does the energy come from?"}}],"reveal":{"zh":"p = F/S，小面积上小力产生大压强，传到大面积上就是大力；小活塞移动距离长、大活塞移动距离短，能量仍守恒。","en":"p = F/S: a small force on a small area makes a large pressure, which on a large area becomes a large force; the small piston travels far and the big one travels little, so energy is still conserved."},"source":"../physics/matter/pressure/#step0","lesson":"pressure"},
"q-sound-waves-0":{"target":{"node":"sound-waves","href":"../physics/waves/sound-waves/#step1"},"prompts":[{"node":"superposition","ask":{"zh":"两个相近频率的声音叠加会产生拍——拍的快慢由什么决定？","en":"Two close frequencies played together produce beats — what sets how fast the beats come?"}},{"node":"sound-waves","ask":{"zh":"同一个音，钢琴和小提琴的波形有什么不同？谐波的强弱决定什么？","en":"For the same note, how do a piano's and a violin's waveforms differ? What do the strengths of the harmonics decide?"}},{"node":"fourier","ask":{"zh":"傅里叶分析能把复杂波形拆成什么？拆开后怎样解释音色不同？","en":"What does Fourier analysis break a complex waveform into? How does that explain different timbres?"}}],"reveal":{"zh":"拍来自相近频率的叠加；音色由谐波的组成与强弱决定，傅里叶分析把波形拆成不同频率的正弦波，组成不同听起来就不同。","en":"Beats come from superposing close frequencies; timbre is set by which harmonics are present and how strong they are — Fourier analysis splits a waveform into sine waves of different frequencies, and different mixtures sound different."},"source":"../physics/waves/sound-waves/#step1","lesson":"sound-waves"},
"q-doppler-effect-0":{"target":{"node":"doppler-effect","href":"../physics/waves/doppler-effect/#step2"},"prompts":[{"node":"superposition","ask":{"zh":"运动声源的波前被挤密或拉疏——声源靠近你时，波前挤密会让频率变高还是变低？","en":"A moving source bunches or stretches its wavefronts — as it approaches you, does bunching raise or lower the frequency?"}},{"node":"doppler-effect","ask":{"zh":"救护车掠过你身边的一刻，听到的频率怎样跳变？掠过曲线在前后各是什么样？","en":"At the moment the ambulance sweeps past you, how does the heard frequency jump? What does the pass-by curve look like before and after?"}},{"node":"spectrum","ask":{"zh":"把声音按频率展开成谱——靠近和远离时，谱峰往哪个方向移？","en":"Spread the sound out by frequency into a spectrum — which way does the peak shift on approach and on retreat?"}}],"reveal":{"zh":"靠近时波前挤密、频率变高，远离时拉疏、频率变低，掠过瞬间音调跳变；这就是多普勒效应。","en":"Approaching bunches the wavefronts and raises the frequency, retreating stretches them and lowers it, with a jump as it passes — the Doppler effect."},"source":"../physics/waves/doppler-effect/#step2","lesson":"doppler-effect"},
"q-newton-laws-0":{"target":{"node":"newton-laws","href":"../physics/mechanics/newton-laws/#step2"},"prompts":[{"node":"newton-laws","ask":{"zh":"同样的合力推箱子，质量越大加速度怎样？加速度由合力和质量怎样决定？","en":"Push boxes with the same net force — the heavier the box, the bigger or smaller the acceleration? How do net force and mass set acceleration?"}},{"node":"net-force","ask":{"zh":"频闪残影里，加速度是怎样看出来的？摩擦和斜面会改变合力吗？","en":"In stroboscopic ghosts, how do you read off acceleration? Do friction and ramps change the net force?"}}],"reveal":{"zh":"a = F/m，合力相同质量越大加速度越小；摩擦和斜面都改变合力，所以加速也跟着变。","en":"a = F/m: same net force with more mass means less acceleration; friction and ramps change the net force, so acceleration changes with them."},"source":"../physics/mechanics/newton-laws/#step2","lesson":"newton-laws"},
"q-projectile-circular-0":{"target":{"node":"projectile-circular","href":"../physics/mechanics/projectile-circular/#step4"},"prompts":[{"node":"net-force","ask":{"zh":"抛体运动可把速度分成水平和竖直两份——水平方向受力吗？竖直方向呢？","en":"Projectile motion splits velocity into horizontal and vertical parts — is there a force horizontally? Vertically?"}},{"node":"projectile-circular","ask":{"zh":"匀速圆周需要向心加速度——卫星绕地球转，向心力由什么提供？","en":"Uniform circular motion needs centripetal acceleration — for a satellite circling Earth, what supplies the centripetal force?"}}],"reveal":{"zh":"卫星水平速度约 7.9 km/s 时，下落的弧度正好跟上地球表面的弯曲，于是绕着地球转而不掉下来；11.2 km/s 就脱离。","en":"At about 7.9 km/s sideways, the satellite's fall curves exactly with Earth's surface, so it circles without landing; 11.2 km/s escapes."},"source":"../physics/mechanics/projectile-circular/#step4","lesson":"projectile-circular"},
"q-resonance-0":{"target":{"node":"resonance","href":"../physics/waves/resonance/#step3"},"prompts":[{"node":"oscillation","ask":{"zh":"秋千有固有频率——推的节拍和固有频率一致时，每次推动是加能量还是减能量？","en":"A swing has a natural frequency — when your pushes match it, does each push add energy or remove it?"}},{"node":"resonance","ask":{"zh":"阻尼比决定共振曲线多尖——阻尼大时，推偏一点节拍还能推起来吗？","en":"The damping ratio sets how sharp the resonance curve is — with heavy damping, can you still build up the swing pushing slightly off-beat?"}},{"node":"freqresp","ask":{"zh":"稳态振幅最大时，相位滞后是多少？推力和运动是什么关系？","en":"At maximum steady-state amplitude, what is the phase lag? How do push and motion relate?"}}],"reveal":{"zh":"踩中固有频率，每次推动都顺着运动加能量，振幅越推越大；节拍偏了，能量时加时减，推不起来。","en":"Push at the natural frequency and every push feeds energy in phase, so amplitude builds; off-beat, energy alternately adds and cancels, and the swing never builds up."},"source":"../physics/waves/resonance/#step3","lesson":"resonance"},
"q-seismic-waves-0":{"target":{"node":"seismic-waves","href":"../earth/geo/seismic-waves/#step3"},"prompts":[{"node":"snell","ask":{"zh":"P 波快、S 波慢——用 S−P 时间能估出震中距，为什么还需要三个台站才能定位？","en":"P is fast and S is slow — S−P time estimates the epicentre distance, so why do you need three stations to locate it?"}},{"node":"seismic-waves","ask":{"zh":"S 波被液态外核挡住——如果外核是固态，S 波会怎样？P 波影区又说明什么？","en":"S waves are blocked by the liquid outer core — if it were solid, what would S waves do? And what does the P-wave shadow zone tell us?"}}],"reveal":{"zh":"S 波穿不过液态外核、P 波有影区，波线弯曲和影区位置合起来说明外核是液体；没人下去也能从波里读出地球内部。","en":"S waves cannot cross a liquid outer core and P waves leave a shadow zone; the bending rays and shadow pattern together say the outer core is liquid — Earth's interior read from waves alone."},"source":"../earth/geo/seismic-waves/#step3","lesson":"seismic-waves"},
"q-standing-wave-0":{"target":{"node":"standing-wave","href":"../physics/waves/standing-wave/#step3"},"prompts":[{"node":"standing-wave","ask":{"zh":"两端钉死时，哪些波长能在弦上稳定存在？","en":"With both ends fixed, which wavelengths can survive on the string?"}},{"node":"resonance","ask":{"zh":"拨弦或驱动时，为什么只有对上固有频率的振动会变大？","en":"When plucked or driven, why do only vibrations at natural frequencies grow large?"}}],"reveal":{"zh":"两端固定要求两端始终是波节，所以只有 L = nλ/2 的波长能稳定存在，频率排成 f₁、2f₁、3f₁……的台阶。拨弦激起的正是这些模式，基频定音高，各次谐波的配比定音色。","en":"Fixed ends must always be nodes, so only wavelengths with L = nλ/2 survive and the frequencies form steps f₁, 2f₁, 3f₁, … Plucking excites exactly these modes: the fundamental sets the pitch and the mix of harmonics sets the tone."},"source":"../physics/waves/standing-wave/#step3","lesson":"standing-wave"},
"q-double-slit-0":{"target":{"node":"double-slit","href":"../physics/modern/double-slit/#step2"},"prompts":[{"node":"double-slit","ask":{"zh":"一颗颗粒子的落点怎样累积成条纹？知道走了哪条缝时条纹为什么消失？","en":"How do single particles' landing dots build up into fringes? Why do the fringes vanish once you know which slit was used?"}},{"node":"interference","ask":{"zh":"路程差怎样决定明暗？条纹间距 Δy = λL/d 里每个字母是什么意思？","en":"How does path difference decide bright and dark? In the fringe spacing Δy = λL/d, what does each letter mean?"}},{"node":"superposition","ask":{"zh":"概率幅相加和普通概率相加有什么不同？为什么“同时走两条缝”其实是振幅在相加？","en":"How does adding probability amplitudes differ from adding ordinary probabilities? Why does “taking both slits at once” really mean amplitudes adding?"}}],"reveal":{"zh":"双缝条纹间距 Δy = λL/d，被单缝 sinc² 包络罩住。一颗颗粒子的落点累积成条纹，因为概率幅按叠加相加、路程差决定明暗，而知道走了哪条缝则条纹消失。","en":"Double-slit fringes are spaced Δy = λL/d under a single-slit sinc² envelope. Single particles build the fringes dot by dot because probability amplitudes add by superposition, with path difference deciding bright and dark — and knowing which slit was used erases them."},"source":"../physics/modern/double-slit/#step2","lesson":"double-slit"},
"q-gravitational-lensing-0":{"target":{"node":"gravitational-lensing","href":"../earth/astronomy/gravitational-lensing/#step2"},"prompts":[{"node":"gravitational-lensing","ask":{"zh":"质量使光偏折 α = 4GM/(c²b)——质量越大、光线离得越近，偏折越大还是越小？","en":"Mass deflects light by α = 4GM/(c²b) — bigger mass, closer pass: bigger or smaller deflection?"}},{"node":"snell","ask":{"zh":"点质量透镜方程给出两个像——光源、透镜、观测者恰好在一条线上时，两个像变成什么？","en":"The point-mass lens equation gives two images — when source, lens and observer line up exactly, what do the two images become?"}}],"reveal":{"zh":"光源在连线上时，两个像连成一个环——爱因斯坦环；环的大小随透镜质量平方根增大，所以能由环称出透镜质量。","en":"With the source on the line, the two images join into a ring — an Einstein ring; its size grows with the square root of the lens mass, so the ring weighs the lens."},"source":"../earth/astronomy/gravitational-lensing/#step2","lesson":"gravitational-lensing"},
"q-kinetic-theory-0":{"target":{"node":"kinetic-theory","href":"../physics/thermal/kinetic-theory/#step0"},"prompts":[{"node":"work-energy","ask":{"zh":"压强是撞墙冲量——分子撞墙越猛、越频繁，压强越大还是越小？","en":"Pressure is wall impulse — harder, more frequent wall collisions: bigger or smaller pressure?"}},{"node":"kinetic-theory","ask":{"zh":"温度是平均动能——温度升高，分子的平均动能怎样变？速率分布的形状怎样变？","en":"Temperature is mean kinetic energy — as temperature rises, how does mean kinetic energy change? How does the speed distribution's shape change?"}},{"node":"probability","ask":{"zh":"碰撞怎样生成麦克斯韦速率分布？分布是事先设定的还是碰撞自然产生的？","en":"How do collisions generate the Maxwell speed distribution? Is the distribution preset, or does it emerge from collisions?"}}],"reveal":{"zh":"压强是大量分子撞墙的冲量平均，温度是平均动能；碰撞不断交换能量，自然生成麦克斯韦速率分布。","en":"Pressure is the average impulse of countless wall collisions, temperature is mean kinetic energy; collisions constantly exchange energy and the Maxwell speed distribution emerges on its own."},"source":"../physics/thermal/kinetic-theory/#step0","lesson":"kinetic-theory"},
"q-modulation-0":{"target":{"node":"modulation","href":"../signal/sampling/modulation/#step5"},"prompts":[{"node":"modulation","ask":{"zh":"几家电台把各自的声音搬到哪里？接收端怎样把想听的那家搬回来？","en":"Where does each station move its audio, and how does the receiver bring back just the one it wants?"}},{"node":"spectrum","ask":{"zh":"在频谱上，不同电台是靠什么分开的？靠得太近会怎样？","en":"On the spectrum, what keeps stations apart, and what happens if they get too close?"}}],"reveal":{"zh":"每家电台用不同的载波频率把声音搬到频谱上各自的一段；收音机用带通滤波圈住目标那一段，再乘上同频载波把它搬回基带。相邻电台的频段一旦重叠进带通，就会串台。","en":"Each station uses its own carrier to move its audio into its own slice of the spectrum; the radio fences off the target slice with a band-pass filter and multiplies by a matching carrier to bring it back to baseband. If a neighbour’s band overlaps the pass band, you hear crosstalk."},"source":"../signal/sampling/modulation/#step5","lesson":"modulation"},
"q-photoelectric-effect-0":{"target":{"node":"photoelectric-effect","href":"../physics/modern/photoelectric-effect/#step1"},"prompts":[{"node":"spectrum","ask":{"zh":"光子能量由频率决定——光再亮，亮的是什么？单个光子的能量变了吗？","en":"A photon's energy is set by frequency — when light gets brighter, what actually brightens? Does a single photon's energy change?"}},{"node":"photoelectric-effect","ask":{"zh":"逸出功和截止频率是什么关系？频率低于截止频率时，再多光子有用吗？","en":"How do work function and threshold frequency relate? Below the threshold frequency, do more photons help?"}},{"node":"interference","ask":{"zh":"遏止电压测出的是什么？怎样用它测出 h？","en":"What does the stopping voltage measure? How can it measure h?"}}],"reveal":{"zh":"打出电子靠单个光子的能量 hν，不是总亮度；频率低于截止频率，单个光子能量不够，逸出功跨不过，再亮也打不出。","en":"Freeing an electron takes a single photon's energy hν, not total brightness; below the threshold frequency each photon is too weak to clear the work function, no matter how bright the light."},"source":"../physics/modern/photoelectric-effect/#step1","lesson":"photoelectric-effect"},
"q-quantum-tunneling-0":{"target":{"node":"quantum-tunneling","href":"../physics/modern/quantum-tunneling/#step1"},"prompts":[{"node":"interference","ask":{"zh":"稳态波函数在势垒内指数衰减——衰减到零了吗？墙后还剩多少？","en":"A steady wave function decays exponentially inside a barrier — does it reach zero? How much remains past the wall?"}},{"node":"quantum-tunneling","ask":{"zh":"透射概率随墙宽指数下降——墙加厚一倍，透射概率是减半还是指数式暴跌？","en":"Transmission falls exponentially with wall width — double the wall, and does transmission halve or crash exponentially?"}}],"reveal":{"zh":"波函数在墙内指数衰减但不到零，墙后留有透射份额；墙越宽、粒子越重，透射概率指数式越小，扫描隧道显微镜正是用这指数灵敏度成像。","en":"The wave function decays exponentially inside the wall but never reaches zero, leaving a transmitted share; wider walls and heavier particles shrink transmission exponentially, and the scanning tunnelling microscope images with exactly that exponential sensitivity."},"source":"../physics/modern/quantum-tunneling/#step1","lesson":"quantum-tunneling"},
"q-relativity-0":{"target":{"node":"relativity","href":"../physics/modern/relativity/#step1"},"prompts":[{"node":"net-force","ask":{"zh":"光速不变出发——光钟的时间膨胀说明什么？运动的钟变快还是变慢？","en":"Starting from a constant speed of light — what does a light clock's time dilation show? Does a moving clock run fast or slow?"}},{"node":"relativity","ask":{"zh":"同时性的相对性是什么意思？两个惯性观察者对“同时”会达成一致吗？","en":"What does the relativity of simultaneity mean? Will two inertial observers agree on what is “simultaneous”?"}}],"reveal":{"zh":"光速不变推出时间膨胀、同时相对；有质量粒子越近光速，动能发散到无穷，所以永远到不了光速。","en":"A constant speed of light forces time dilation and relative simultaneity; a massive particle's kinetic energy diverges as it nears light speed, so it can never reach it."},"source":"../physics/modern/relativity/#step1","lesson":"relativity"},
"q-wavelets-0":{"target":{"node":"wavelets","href":"../signal/transforms/wavelets/#step2"},"prompts":[{"node":"fourier","ask":{"zh":"傅里叶幅度谱说明有哪些频率——它告诉你频率出现的先后吗？","en":"A Fourier magnitude spectrum shows which frequencies are present — does it say when each occurs?"}},{"node":"spectrum","ask":{"zh":"加窗后分析怎样同时定位时间与频率？窗口窄了，时间定位和频率定位各怎样变？","en":"How does windowing locate time and frequency together? With a narrower window, how do time and frequency localisation each change?"}},{"node":"wavelets","ask":{"zh":"小波和加窗傅里叶有什么不同？Morlet 小波为什么适合这件事？","en":"How do wavelets differ from windowed Fourier? Why is the Morlet wavelet suited to this?"}}],"reveal":{"zh":"傅里叶谱只说有哪些频率、不说何时出现；加窗和小波把信号切成时段再分析频率，时间与频率就同时定位了。","en":"A Fourier spectrum lists frequencies but not their timing; windowing and wavelets slice the signal into time spans before analysing frequency, locating time and frequency together."},"source":"../signal/transforms/wavelets/#step2","lesson":"wavelets"}
}});
